/* ========== CELEBRATION CONFETTI ========== */
.celebration-layer {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 998;
  overflow: hidden;
}
.confetti {
  position: absolute;
  width: 10px;
  height: 10px;
  top: -20px;
  animation: confettiFall linear forwards;
}
@keyframes confettiFall {
  0%   { transform: translateY(-20px) rotate(0deg); opacity: 1; }
  100% { transform: translateY(110vh) rotate(720deg); opacity: 0.3; }
}

/* ========== RESULT ENTRANCE ========== */
.result-banner.animate-pop {
  animation: popIn 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes popIn {
  0%   { transform: scale(0); opacity: 0; }
  70%  { transform: scale(1.15); }
  100% { transform: scale(1); opacity: 1; }
}
.result-emoji.animate-bounce {
  animation: bounce 1s ease infinite;
}
@keyframes bounce {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-14px); }
}
.result-info.animate-stagger > * {
  animation: slideIn 0.5s ease forwards;
  opacity: 0;
}
.result-info.animate-stagger > *:nth-child(2) { animation-delay: 0.15s; }
.result-info.animate-stagger > *:nth-child(3) { animation-delay: 0.30s; }
.result-info.animate-stagger > *:nth-child(4) { animation-delay: 0.45s; }
@keyframes slideIn {
  from { opacity: 0; transform: translateX(20px); }
  to   { opacity: 1; transform: translateX(0); }
}

/* ========== VIBRATION (mobile) ========== */
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25%      { transform: translateX(-5px); }
  75%      { transform: translateX(5px); }
}
.urgent-shake { animation: shake 0.3s ease 3; }

/* ========== COVER ========== */

