  const colors = ['#f5c842','#1abc9c','#e74c3c','#3498db','#9b59b6','#ffffff','#2ecc71'];
  const shapes = ['●', '■', '▲', '★', '◆'];

  for (let i = 0; i < 80; i++) {
    const el = document.createElement('div');
