function updateTimer() {
  const m = Math.floor(game.timeLeft / 60).toString().padStart(2, '0');
  const s = (game.timeLeft % 60).toString().padStart(2, '0');
  const digits = document.getElementById('timer');
  digits.textContent = `${m}:${s}`;
  digits.className = 'timer-digits' + (game.timeLeft <= 30 ? ' urgent' : '');

  // صوت
  if (game.timeLeft <= 10 && game.timeLeft > 0) {
    playUrgentSound();
    if (navigator.vibrate) navigator.vibrate(80);
  } else if (game.timeLeft > 0 && game.timeLeft % 60 === 0) {
    playTickSound();
  }

  // Cercle SVG
  const ring = document.getElementById('timer-ring-el');
  if (ring) {
    const total = 2 * Math.PI * 68;
    const progress = game.timeLeft / game.totalTime;
    ring.style.strokeDashoffset = total * (1 - progress);
    ring.style.stroke = game.timeLeft <= 30 ? '#e74c3c' : 'var(--gold)';
  }
}

