function renderThemeButtons() {
  // استخراج الفئات الفريدة مع عددها
  const cats = {};
  GAME_CONTENT.forEach(e => { cats[e.categorie] = (cats[e.categorie]||0)+1; });

  const themeEmojis = {
    'نبي': '🧕', 'سورة': '📖', 'قصة': '📜', 'حدث': '⚔️',
    'معجزة': '✨', 'مكان': '🕌', 'شخصية': '👤', 'ركن': '🕋',
    'عبادة': '🤲', 'مفهوم': '💭', 'دعاء': ' dua', 'خُلُق': '❤️',
    'علم': '📚'
  };
  themeEmojis['دعاء'] = '🤲';

  const keys = Object.keys(cats).sort((a,b) => cats[b]-cats[a]);
  let html = `<button class="vote-btn selected" data-theme="الكل" onclick="selectTheme('الكل')">
      <div class="vote-avatar">🎲</div>
      <span>كل المواضيع (${GAME_CONTENT.length} كلمة)</span>
    </button>`;
  keys.forEach(k => {
    const emoji = themeEmojis[k] || '✦';
    html += `<button class="vote-btn" data-theme="${escapeHtml(k)}" onclick="selectTheme('${escapeHtml(k)}')">
      <div class="vote-avatar">${emoji}</div>
      <span>${escapeHtml(k)} (${cats[k]} كلمة)</span>
    </button>`;
  });
  document.getElementById('themeButtons').innerHTML = html;
  game.selectedTheme = 'الكل';
}

function selectTheme(theme) {
  document.querySelectorAll('#themeButtons .vote-btn').forEach(b => b.classList.remove('selected'));
  document.querySelector(`#themeButtons .vote-btn[data-theme="${theme}"]`).classList.add('selected');
  game.selectedTheme = theme;
}

function confirmTheme() {
  const theme = game.selectedTheme || 'الكل';
  // اختيار كلمة عشوائية من الموضوع المختار
