for (let p = 0; p < game.numPlayers; p++) {
  game.currentPlayer = p;
  revealRole();
  nextPlayer();
}
check('كل اللاعبين شاهدوا أدوارهم', game.currentPlayer >= game.numPlayers);

// TEST 4: مؤقت النقاش
check('المؤقت مضبوط', game.timeLeft === 120);

