const cats = {};
GAME_CONTENT.forEach(e => cats[e.categorie] = (cats[e.categorie]||0)+1);
check('عدد الفئات: ' + Object.keys(cats).length, Object.keys(cats).length > 15);
check('إجمالي الكلمات: ' + GAME_CONTENT.length, GAME_CONTENT.length >= 400);

// TEST 8: كل فئة قابلة للاختيار
let allOk = true;
Object.keys(cats).forEach(cat => {
  const pool = GAME_CONTENT.filter(e => e.categorie === cat);
  if (pool.length === 0) allOk = false;
});
check('كل الفئات فيها كلمات', allOk);
`, ctx);

const failed = tests.filter(t => !t[1]);
console.log('\\n--- النتيجة: ' + (tests.length - failed.length) + '/' + tests.length + ' نجح ---');
process.exit(failed.length ? 1 : 0);
EOF
